package com.starlight.greetings.web;
import com.starlight.greetings.application.LetterWriteService; import com.starlight.greetings.application.LetterWriteResult; import com.starlight.greetings.application.SessionService;
import java.util.Map;
import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/bridges/{bridgeId}/letters") public class LetterWriteController { private final LetterWriteService letters;private final SessionService sessions; public LetterWriteController(LetterWriteService letters,SessionService sessions){this.letters=letters;this.sessions=sessions;} @PostMapping public ResponseEntity<ApiEnvelope<Map<String,String>>> write(@PathVariable String bridgeId,@RequestBody Map<String,Object> body,@RequestHeader("idempotency-key") String key,@RequestHeader(value="x-csrf-token",required=false) String csrf,jakarta.servlet.http.HttpServletRequest request){String token=null;if(request.getCookies()!=null)for(var c:request.getCookies())if("star_session_dev".equals(c.getName()))token=c.getValue();var user=sessions.member(token,csrf);body.put("bridgeId",bridgeId);body.put("idempotencyKey",key);body.put("userId",user.id());body.put("nickname",user.nickname());LetterWriteResult result=letters.write(body);return ResponseEntity.status(result.replayed()?200:201).body(ApiEnvelope.of(Map.of("id",result.id())));}
 // 편지 쓰기 화면에 보여줄 오늘 남은 작성 횟수(조회라 CSRF 없이 로그인 회원만)
 @GetMapping("/quota") public ApiEnvelope<Map<String,Object>> quota(@PathVariable String bridgeId,jakarta.servlet.http.HttpServletRequest request){var user=sessions.current(SessionCookie.token(request));if(!"member".equals(user.role()))throw new ApiException(org.springframework.http.HttpStatus.FORBIDDEN,"MEMBER_REQUIRED","회원 기능을 이용할 수 없습니다.");return ApiEnvelope.of(letters.quota(user.id(),bridgeId));}}
